arguments.command:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ issues(first: 500) { nodes { id identifier title priority team { key } subscribers { nodes { name } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('total issues:', len(d['data']['issues']['nodes']))
for n in d['data']['issues']['nodes']:
    subs=[s['name'] for s in n['subscribers']['nodes']]
    if 'Sam Rivera' in subs:
        print('SUBSCRIBED:', n['identifier'], '|', n['title'], '| team:', n['team']['key'], '| priority:', n.get('priority'))
print('--- design system titles ---')
for n in d['data']['issues']['nodes']:
    if 'esign system' in n['title'].lower():
        print(n['identifier'], '|', n['title'], '| team:', n['team']['key'], '| subs:', [s['name'] for s in n['subscribers']['nodes']])
"

